local function bxor(a, b)
    if bit32 and bit32.bxor then return bit32.bxor(a, b) end
    if bit and bit.bxor then return bit.bxor(a, b) end
    local r, p = 0, 1
    a, b = a % 256, b % 256
    while a > 0 or b > 0 do
        local ab, bb = a % 2, b % 2
        if ab ~= bb then r = r + p end
        a = math.floor(a / 2)
        b = math.floor(b / 2)
        p = p * 2
    end
    return r
end

local function b64(data)
    if type(crypt) == "table" and type(crypt.base64decode) == "function" then
        local ok, r = pcall(crypt.base64decode, data)
        if ok and r then return r end
    end
    if type(base64) == "table" and type(base64.decode) == "function" then
        local ok, r = pcall(base64.decode, data)
        if ok and r then return r end
    end
    if type(base64_decode) == "function" then
        local ok, r = pcall(base64_decode, data)
        if ok and r then return r end
    end
    local b = {}
    local map = {}
    for i = 0, 25 do
        map[string.char(65 + i)] = i
        map[string.char(97 + i)] = i + 26
    end
    for i = 0, 9 do map[string.char(48 + i)] = 52 + i end
    map["+"] = 62
    map["/"] = 63
    data = tostring(data):gsub("%s+", "")
    local buf, n = 0, 0
    for i = 1, #data do
        local ch = data:sub(i, i)
        if ch == "=" then break end
        local v = map[ch]
        if v then
            buf = buf * 64 + v
            n = n + 1
            if n == 4 then
                local c1 = math.floor(buf / 65536) % 256
                local c2 = math.floor(buf / 256) % 256
                local c3 = buf % 256
                b[#b + 1] = string.char(c1, c2, c3)
                buf, n = 0, 0
            end
        end
    end
    if n == 3 then
        buf = buf * 64
        b[#b + 1] = string.char(math.floor(buf / 65536) % 256, math.floor(buf / 256) % 256)
    elseif n == 2 then
        buf = buf * 64 * 64
        b[#b + 1] = string.char(math.floor(buf / 65536) % 256)
    end
    return table.concat(b)
end

local function xordec(s)
    local out = {}
    local kl = #K
    for i = 1, #s do
        out[i] = string.char(bxor(string.byte(s, i), K[((i - 1) % kl) + 1]))
    end
    return table.concat(out)
end

local decoded = {}
for i = 1, #C do
    local blob = C[i]
    if type(blob) ~= "string" or #blob == 0 then
        error("[HONKUKI] empty chunk " .. tostring(i))
    end
    local ok, plain = pcall(function()
        return xordec(b64(blob))
    end)
    if not ok or type(plain) ~= "string" then
        error("[HONKUKI] decode fail chunk " .. tostring(i) .. " " .. tostring(plain))
    end
    decoded[i] = plain
end

local source = table.concat(decoded)
local loaderFn = loadstring or load
if type(loaderFn) ~= "function" then
    error("[HONKUKI] no loadstring/load")
end
local fn, err = loaderFn(source)
if type(fn) ~= "function" then
    error("[HONKUKI] compile: " .. tostring(err))
end
return fn()
